import{_ as t,o as a,c as e,ai as o}from"./chunks/framework.Ai2o9gNv.js";const s="/assets/image-20260302215008064.BwVxO7SH.png",p="/assets/image-20260302225540201.BtjLW7bN.png",i="/assets/image-20260302215354241.3Vs3_Uk8.png",r="/assets/image-20260302221058514.CSHvyDC_.png",l="/assets/image-20260302221223686.DZ6FDVgA.png",b="/assets/image-20260302221541820.CaLQn-CS.png",g="/assets/image-20260302223541761.B81bEhhj.png",c="/assets/image-20260302225305824.BtcUwQAL.png",d="/assets/image-20260302225329053.br-Y2DtW.png",h="/assets/image-20260302225352010.HNGQrrdg.png",m="/assets/image-20260302225423725.DUEB-UB_.png",w="/assets/image-20260302221302515.CN7n6_E1.png",A="/assets/image-20260302221352733.B-Gaxgz9.png",_="/assets/image-20260302221446749.BMCf2pn5.png",B=JSON.parse('{"title":"体验了下美团的Tabbit浏览器，可能你都不需要OpenClaw","description":"","frontmatter":{},"headers":[],"relativePath":"AI人工智能/体验了下美团的Tabbit 浏览器，可能你都不需要openclaw/体验了下美团的Tabbit 浏览器，可能你都不需要openclaw.md","filePath":"AI人工智能/体验了下美团的Tabbit 浏览器，可能你都不需要openclaw/体验了下美团的Tabbit 浏览器，可能你都不需要openclaw.md","lastUpdated":1772463590000,"__rawMarkdown":"# 体验了下美团的Tabbit浏览器，可能你都不需要OpenClaw\\n\\n> 万少：华为HDE、鸿蒙极客\\n> \\n> 个人主页：[https://blog.zbztb.cn/](https://blog.zbztb.cn/)\\n> \\n> **2025年参与孵化了20+鸿蒙应用、技术文章300+、鸿蒙知识库用户500+、鸿蒙免费课程2套。**\\n> \\n> 如果你也喜欢交流AI和鸿蒙技术，欢迎扣我。\\n\\n\\n\\n> https://www.tabbit-ai.com/\\n\\n![](assets/image-20260302215008064.png)\\n\\n## 写在前面：AI Agent的两种形态\\n\\n\\n\\n最近，美团旗下光年之外团队推出了首款AI原生浏览器**Tabbit**，正式开启免费公测。作为一名长期关注AI自动化工具的开发者，我第\\n\\n\\n\\n一时间下载体验了这款产品。说实话，用完之后我有一个强烈的感受：**对于那些只是想用AI简化日常浏览和工作流程的普通用户**\\n\\n**来说，你可能真的不需要折腾OpenClaw了。​**\\n\\n\\n\\n这并不是说**OpenClaw**不够好——恰恰相反，它是一个非常强大的开源项目，GitHub上狂揽二十多万星，被誉为**个人AI管家**。但问题\\n\\n在于，**强大往往意味着复杂**。而**Tabbit**的出现，似乎找到了一个更优雅的平衡点。\\n\\n![](assets/image-20260302225540201.png)\\n\\n---\\n\\n## OpenClaw：极客的神器，普通人的门槛\\n\\n![](assets/image-20260302215354241.png)\\n\\n在深入聊Tabbit之前，有必要先理解一下OpenClaw是什么，以及为什么它让那么多开发者为之疯狂。\\n\\n\\n\\nOpenClaw（前身为Clawdbot/Moltbot）是一个**自托管的AI Agent运行时环境**。简单来说，它能在你的电脑上持续运行，通过\\n\\nWhatsApp、Telegram、Slack等聊天应用与你交互，并且能够：\\n\\n- 执行Shell命令和脚本\\n- 控制浏览器完成自动化操作\\n- 读写本地文件\\n- 管理日历和邮件\\n- 甚至自己编写代码来扩展能力\\n\\n听起来很美好对吧？但问题在于，要让它真正跑起来，你需要：\\n\\n1. **一台配置不低的服务器**（推荐4GB内存起步）\\n2. **熟练的Docker和Linux操作能力**\\n3. **配置各种API密钥和环境变量**\\n4. **理解它的工具策略、技能机制、沙盒配置**\\n5. **时刻警惕安全风险**（毕竟它能执行系统级命令）\\n\\n一位Reddit用户的吐槽非常精准：\\"我花了一周时间测试OpenClaw，最终并没有减少工作量，而是得到了一件需要管理的新东西。\\"\\n\\n\\n\\n这就是OpenClaw的本质——**它是为开发者和极客设计的乐高积木，而不是即拿即用的成品工具。​**\\n\\n---\\n\\n## Tabbit：开箱即用的\\"轻量版OpenClaw\\"\\n\\n\\n\\n如果说OpenClaw是DIY爱好者的终极玩具，那么Tabbit就是**产品经理为普通用户精心打磨的成品**。\\n\\n### 核心定位的差异\\n\\n| 维度 | OpenClaw | Tabbit |\\n|------|----------|--------|\\n| **使用门槛** | 需要技术背景，自托管部署 | 下载安装即用，零配置 |\\n| **运行环境** | 独立服务器/本地后台服务 | 作为浏览器正常运行 |\\n| **交互方式** | 通过第三方聊天应用 | 内置侧边栏对话界面 |\\n| **目标用户** | 开发者、技术极客 | 上班族、学生、内容创作者 |\\n| **安全模型** | 用户自行配置权限策略 | 内置沙箱隔离，开箱安全 |\\n\\nTabbit的最大创新在于，它将AI Agent的能力**原生集成到了浏览器这个 everyday tool 中**。你不需要学习新的交互习惯，也不需要维\\n\\n护额外的服务——打开浏览器，就能开始用自然语言指挥AI帮你干活。\\n\\n---\\n\\n## Tabbit的三大杀手锏功能\\n\\n在实际体验中，我发现Tabbit有三个功能特别值得一提，它们分别对应了OpenClaw的核心能力，但实现方式更加优雅：\\n\\n### 1. 智能代理模式\\n\\n这是Tabbit对标OpenClaw\\"浏览器自动化\\"能力的核心功能。\\n\\n举个例子：\\n\\n> 帮我搜索 ID为万少的在全网中关于HarmonyOS文章列表，帮我整理成表格，并且需要带上真实可用的超链接，最后生成关于万少的个人背景介绍\\n\\n接下来，Tabbit会：\\n- 在全网中开始搜索这个主题\\n- 然后生成总结\\n\\n![](assets/image-20260302221058514.png)\\n\\n整个过程在一个独立的标签组中运行，不会干扰我当前的其他浏览内容，最终得到的结果如下：\\n\\n![](assets/image-20260302221223686.png)\\n\\n---\\n\\n\\n\\n这与OpenClaw的浏览器自动化能力本质上是一样的——都是让AI模拟人类操作网页。\\n\\n\\n\\n但Tabbit的优势在于**无缝集成**：不需要额外启动浏览器实例，不需要配置CDP协议，更不用担心权限管控。\\n\\n### 2. 妙招（Skill）\\n\\n![](assets/image-20260302221541820.png)\\n\\nOpenClaw有一个**技能（Skill）**系统，允许用户通过编写`SKILL.md`文件来扩展Agent的能力。这很强大，但也很有门槛。\\n\\n\\n\\nTabbit的\\"妙招\\"功能则是**完全零代码**的。你可以把任何高频使用的提问方式、格式规范或工作流程保存为一键调用的快捷指令。\\n\\n\\n\\n比如我经常需要阅读论文时查专业术语，于是创建了一个\\"论文解释\\"妙招。以后只要选中不懂的名词，输入`/论文解释`，就能立即\\n\\n获得通俗易懂的解释。\\n\\n\\n\\n官方还提供了述职报告、文本润色、内容总结等预设妙招，直接输入`/`就能调用。这种设计思路与苹果的\\"快捷指令\\"类似，但底层\\n\\n\\n\\n是基于大模型的自然语言理解，而非固定的步骤编排。\\n\\n### 3. 脚本功能\\n\\n这可能是Tabbit最让我惊喜的功能——**用自然语言描述需求，自动生成并执行网页脚本**。\\n\\n![](assets/image-20260302223541761.png)\\n\\n我在某个页面上对Tabbit说：\\n\\n> 下载当前页面可见的图片\\n\\n![](assets/image-20260302225305824.png)\\n\\n\\n\\n---\\n\\n![](assets/image-20260302225329053.png)\\n\\n此时，你可以直接点击**执行**\\n\\n![](assets/image-20260302225352010.png)\\n\\n最终得到结果\\n\\n![](assets/image-20260302225423725.png)\\n\\n在OpenClaw的世界里，要实现同样的功能，你可能需要编写复杂的代码和选择器。而在Tabbit中，这一切都被封装在了一句自然语\\n\\n言指令背后。\\n\\n---\\n\\n## 多模型支持\\n\\n![](assets/image-20260302221302515.png)\\n\\nTabbit的另一个亮点是**不绑定单一模型**。它集成了DeepSeek、GLM、Kimi、通义千问、豆包、MiniMax等国内外主流大模型，用户\\n\\n可以根据场景自由切换。\\n\\n这种**模型无关**的设计非常重要。OpenClaw虽然也支持多模型，但需要用户自行配置API密钥和管理配额。Tabbit则通过统一的\\"全能\\n\\n输入框（Omnibox）\\"将这些复杂性隐藏起来，让用户专注于任务本身，而非模型选型。\\n\\n---\\n\\n## 垂直标签管理与全域引用\\n\\n![](assets/image-20260302221352733.png)\\n\\n除了核心的AI能力，Tabbit在浏览器基础体验上也做了不少创新：\\n\\n\\n\\n**垂直标签栏+智能分组**：传统的水平标签栏在打开大量页面时会变得难以管理。Tabbit采用垂直布局，并且能自动识别同类任务，将\\n\\n相关标签页一键归类整理。这对于经常需要同时处理多个项目的用户来说非常实用。\\n\\n\\n\\n**全域引用（@功能）​**：在对话框中输入`@`，可以引用标签组、截图、本地文件等内容作为上下文。\\n\\n![](assets/image-20260302221446749.png)\\n\\n这意味着你可以对Tabbit说：**总结一下@昨天看的那个PDF的重点**，而不需要重新上传文件或描述内容。\\n\\n\\n\\n这些细节看似微小，却体现了产品团队对**真实工作场景**的深刻理解。\\n\\n---\\n\\n## 什么时候你还是需要OpenClaw？\\n\\n说了这么多Tabbit的优点，我必须诚实地说：**它并不能完全替代OpenClaw**。\\n\\n如果你有以下需求，OpenClaw仍然是更好的选择：\\n\\n1. **深度系统集成**：需要操作本地文件系统、执行Shell命令、管理系统级任务\\n2. **跨平台自动化**：需要在多个独立系统之间流转数据（如从ERP同步到CRM）\\n3. **定时任务**：需要按固定周期自动执行某些操作（如每天早8点发送日报）\\n4. **自定义扩展**：需要编写复杂的自定义逻辑，或接入内部专有系统\\n5. **数据隐私极致要求**：希望所有数据和计算都在本地完成，不上传任何云端\\n\\nOpenClaw的本质是一个**通用的AI Agent操作系统**，而Tabbit是一个**专门优化过的AI浏览器**。两者的定位不同，适用的场景也不同。\\n\\n---\\n\\n## 结语：AI工具正在分层\\n\\nTabbit的推出，让我看到了AI工具发展的一个清晰趋势：**分层化**。\\n\\n- **底层**：像**OpenClaw**这样的开源框架，为开发者和企业提供无限可能的定制空间\\n- **中间层**：各类垂直领域的AI应用（如AI编程助手、AI设计工具）\\n- **顶层**：像**Tabbit**这样面向普通消费者的**开箱即用**型产品\\n\\n对于大多数非技术背景的上班族、学生、内容创作者来说，Tabbit提供了一个**足够好用、无需学习成本**的入口，让他们也能享受到AI Agent带来的效率提升。而对于那些愿意投入时间折腾的极客，OpenClaw依然是探索AI自动化边界的最佳 playground。\\n\\n从这个角度看，Tabbit和OpenClaw并不是竞争关系，而是**共同拓展了AI Agent的用户边界**——前者降低了入门门槛，后者则不断推高能力上限。\\n\\n如果你一直在观望AI Agent，却因为OpenClaw的复杂度而望而却步，不妨试试Tabbit。它可能就是你等待的那个\\"刚刚好\\"的产品。\\n\\n---\\n\\n*Tabbit目前已开放公测，支持macOS和Windows平台，官网[tabbit-ai.com](https://www.tabbit-ai.com)可直接下载，公测期间免费且无需邀请码。*\\n\\n\\n\\n\\n\\n## 关于我\\n\\n**关注我**，持续分享**鸿蒙开发** + `AI` 提效的实战技巧。\\n\\n![](https://blog.zbztb.cn/assets/%E5%BE%AE%E4%BF%A1%E5%8F%B7%E5%92%8C%E4%BA%8C%E7%BB%B4%E7%A0%81.KtucpRsB.jpg)"}'),T={name:"AI人工智能/体验了下美团的Tabbit 浏览器，可能你都不需要openclaw/体验了下美团的Tabbit 浏览器，可能你都不需要openclaw.md"};function u(C,n,I,O,q,k){return a(),e("div",null,[...n[0]||(n[0]=[o("",101)])])}const P=t(T,[["render",u]]);export{B as __pageData,P as default};
